def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find monochrome non-background runs along the four borders.
    segs = []
    for side in ("top", "bottom", "left", "right"):
        vals = (grid[0] if side == "top" else grid[-1] if side == "bottom"
                else [grid[r][0 if side == "left" else -1] for r in range(h)])
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            segs.append({"side": side, "color": vals[i], "lo": i, "hi": j - 1})
            i = j

    # Select matching runs on opposite borders.
    pair = None
    for a in segs:
        for b in segs:
            if a["color"] != b["color"]:
                continue
            if (a["side"], b["side"]) in (("top", "bottom"), ("left", "right")):
                score = min(a["hi"] - a["lo"], b["hi"] - b["lo"])
                if pair is None or score > pair[0]:
                    pair = (score, a, b)

    out = [row[:] for row in grid]
    if pair is None:
        return out
    _, a, b = pair
    boundary_color = a["color"]
    horizontal = a["side"] in ("top", "bottom")
    n = w if horizontal else h

    def is_bar(r, c):
        return grid[r][c] == boundary_color and (
            (a["side"] == "top" and r == 0) or
            (a["side"] == "bottom" and r == h - 1) or
            (a["side"] == "left" and c == 0) or
            (a["side"] == "right" and c == w - 1) or
            (b["side"] == "top" and r == 0) or
            (b["side"] == "bottom" and r == h - 1) or
            (b["side"] == "left" and c == 0) or
            (b["side"] == "right" and c == w - 1)
        )

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != boundary_color]
    marker_positions = {(r, c) for r, c, _ in markers}

    center_a = (a["lo"] + a["hi"]) / 2
    center_b = (b["lo"] + b["hi"]) / 2

    for r0, c0, color in markers:
        coord = c0 if horizontal else r0
        for seg, other in ((a, b), (b, a)):
            lo, hi = seg["lo"], seg["hi"]
            other_center = (other["lo"] + other["hi"]) / 2
            this_center = (lo + hi) / 2
            if lo <= coord <= hi:
                target = coord
            elif other["lo"] <= coord <= other["hi"]:
                target = int(round(coord + this_center - other_center))
            else:
                continue
            if not (0 <= target < n):
                continue

            if seg["side"] == "top":
                cells = [(r, target) for r in range(1, h)]
            elif seg["side"] == "bottom":
                cells = [(r, target) for r in range(h - 2, -1, -1)]
            elif seg["side"] == "left":
                cells = [(target, c) for c in range(1, w)]
            else:
                cells = [(target, c) for c in range(w - 2, -1, -1)]

            for r, c in cells:
                if (r, c) in marker_positions:
                    break
                if not is_bar(r, c):
                    out[r][c] = color

    for r, c, _ in markers:
        out[r][c] = 4
    return out
